// ==========================================================================
// pics-base.js: los dibujos de base (heredados de Letrilandia) y el objeto PICS.
// ==========================================================================
// CÓMO FUNCIONAN LOS DIBUJOS (vale para todos los archivos pics-*.js):
//   - Todos los dibujos viven en el objeto global PICS: PICS['gato'], PICS['mochila']...
//     La CLAVE ('gato') es el nombre del dibujo: es lo que se escribe en los temas (words:[{k:'gato'}]),
//     en los juegos, en los cuentos (items:[['gato',x,y,s]]), en la tienda, etc.
//   - El VALOR es una cadena con el interior de un SVG (sin la etiqueta <svg>): <path>, <circle>,
//     <rect>, <g>... dibujado con el centro en (0,0) dentro del cuadro de -62 a 62 en x y en y
//     (viewBox "-62 -62 124 124"). Se usa K como color del contorno y sw(grosor) para el trazo.
//   - Este archivo crea PICS; los demás (pics-new, pics-a..e, pics-mine) añaden más con
//     Object.assign(PICS,{clave:`...svg...`}). Si dos archivos usan la misma clave, gana el último
//     en el orden de build.sh.
//   - Al arrancar, core.js convierte CADA dibujo de PICS en una imagen: IMG[clave]=svgImg(...)
//     (320 px). Por eso los pics-*.js van antes que core.js en build.sh.
//   - Para pintarlo en el canvas: pic('gato', x, y, tamaño) (core.js), que busca IMG['gato'] por su
//     nombre y lo dibuja centrado en (x,y). Si la clave no existe, no pinta nada (no da error).
//     thing(k,x,y,s) (comps.js) acepta además cosas dibujadas {draw} y caritas 'emo:...'.
//     Variantes: greyOf/picG (en gris, core.js y comps2.js) y shadowOf/picS (sombra, comps2.js).
//   - El NOMBRE que dice Tito no está aquí: está en LEX / LEX2 (core.js o lex.js) y se lee con W_(clave).
//     Si falta, Tito diría la clave tal cual ("botasAgua").
// Globales de este archivo: K (color del contorno), sw(), eye(), smile() (ayudas para escribir SVG),
// PICS, y LUPI_SVG, GLASSES_SVG, HAND_SVG (dibujos sueltos con su propio viewBox; core.js los
// convierte en IMG.lupi, IMG.glasses e IMG.hand: la mano que señala en las pistas).
// Los dibujos de este archivo ya están "resueltos": cadenas fijas sin ${...}.
// ==========================================================================
/* ---------- Dibujos base (de Letrilandia), ya resueltos ---------- */
// K: color marrón oscuro de todos los contornos (también se usa en el canvas: ctx.strokeStyle=K).
const K="#4A3428";
// Devuelve los atributos SVG de un trazo de contorno: color K, grosor w y puntas y uniones redondeadas.
const sw=(w=5)=>`stroke="${K}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"`;
// Devuelve un ojo SVG: círculo oscuro de radio r en (x,y) con un brillo blanco arriba a la derecha.
const eye=(x,y,r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${K}"/><circle cx="${x+r*.35}" cy="${y-r*.35}" r="${r*.35}" fill="#fff"/>`;
// Devuelve una sonrisa SVG (curva) que empieza en (x-w, y) y mide 2w de ancho.
const smile=(x,y,w=10)=>`<path d="M${x-w} ${y} q${w} ${w*.7} ${w*2} 0" fill="none" ${sw(3.5)}/>`;
